-- ============================================================
-- 08. 명품 고운발(p9) 상세페이지 — 제조사 원본(3wbmall) 반영
--     실행: Supabase 대시보드 → SQL Editor에 붙여넣고 Run (재실행 안전)
--
--     · 이미지는 3wbmall 핫링크를 끊고 makenov 자체 호스팅 경로로 교체
--       (assets/img/products/goeunbal/*.jpg — 저장소에 함께 커밋되어 있어야 함)
--     · 본문은 원본 상세 이미지의 내용을 3개 국어로 옮긴 것
-- ============================================================

update products set
  img     = 'assets/img/products/goeunbal/main.jpg',
  gallery = array['assets/img/products/goeunbal/main.jpg'],
  detail  = $json$[{"type":"p","text":{"vi":"Kem chứa urea giúp làm mềm và loại bỏ da chai sần, da khô nứt nẻ ở gót chân, đồng thời cấp ẩm để giữ bàn chân mềm mịn. Kết cấu thẩm thấu nhanh, dùng hằng ngày sau khi tắm.","ko":"우레아 성분이 발뒤꿈치의 굳은살과 건조하게 갈라진 각질을 부드럽게 정돈하고, 동시에 수분을 공급해 매끈한 발을 유지해 줍니다. 흡수가 빠른 제형으로 목욕 후 매일 사용하기 좋습니다.","en":"A urea-based cream that softens and smooths calluses and dry, cracked heels while supplying moisture for soft feet. Its fast-absorbing texture suits daily use after bathing."}},{"type":"p","text":{"vi":"Thành phần chính: urea làm mềm sừng, cùng chiết xuất sữa ong chúa và keo ong (propolis). Ngoài ra còn có chiết xuất hoa kim ngân, hoa cúc La Mã, acerola, gạo và natri hyaluronate. Kết cấu nhẹ, không cần chà xát hay dũa gót — phù hợp cho cả nam và nữ, mọi lứa tuổi.","ko":"핵심 성분은 각질을 연화시키는 우레아, 그리고 로얄젤리·프로폴리스 추출물입니다. 인동덩굴꽃·마트리카리아(캐모마일)·아세로라·쌀 추출물과 소듐하알루로네이트가 함께 들어갑니다. 가볍게 발리고, 각질을 깎거나 미는 물리적 제거가 필요 없어 남녀노소 모두 사용할 수 있습니다.","en":"Key actives are urea for keratin softening, plus royal jelly and propolis extracts. The formula also carries honeysuckle, chamomile, acerola and rice extracts with sodium hyaluronate. It absorbs lightly and needs no filing or scrubbing, so it suits all ages and genders."}},{"type":"p","text":{"vi":"Kết quả thử nghiệm (theo phiếu kiểm nghiệm của nhà sản xuất): thử nghiệm trên người trong 2 tuần cho thấy vùng da sừng ở gót chân giảm 56,95%; 95,54% người tham gia hài lòng (20 người, tuổi trung bình 34,1 — Human Skin Clinical Trial Center, HD-P24-0036 / IRB HD-IRB-P24-0036, 26/12/2024–09/01/2025). Thử nghiệm patch test kích ứng sơ cấp cho chỉ số 0,00 — xếp loại “không kích ứng (Excellent)”. Kiểm nghiệm 6 kim loại nặng, 6 chất độc hại và giới hạn vi sinh vật: tất cả “không phát hiện” (Korea Institute of Dermatological Sciences).","ko":"시험 결과(제조사 시험성적서 기재값): 2주 인체적용시험에서 뒤꿈치 각질 면적 56.95% 개선, 시험대상자 만족도 95.54%(20명, 평균 34.1세 · 휴먼피부임상시험센터 HD-P24-0036 / IRB HD-IRB-P24-0036, 2024.12.26~2025.01.09). 피부첩포 일차자극 시험 자극지수 0.00 — \"비자극(Excellent)\" 판정. 중금속 6종·유해물질 6종·미생물 한도 시험은 전 항목 불검출(한국피부과학연구원).","en":"Test results as stated on the manufacturer's reports: a 2-week human application study showed 56.95% reduction in heel callus area and 95.54% subject satisfaction (20 subjects, mean age 34.1 — Human Skin Clinical Trial Center, HD-P24-0036 / IRB HD-IRB-P24-0036, 26 Dec 2024–09 Jan 2025). A primary skin irritation patch test returned an index of 0.00, rated \"non-irritating (Excellent)\". Six heavy metals, six hazardous substances and microbial limits were all reported as not detected (Korea Institute of Dermatological Sciences)."}},{"type":"p","text":{"vi":"Thành tích tại thị trường Hàn Quốc (theo tư liệu của nhà sản xuất): hạng 1 doanh số kem dưỡng gót chân trên 11st (12/07/2020) và hạng 1 hạng mục foot cream trong Naver BEST 100 (22/10/2020). Trích dẫn tháng 5/2025: 31.454 đánh giá trên Coupang và 9.630 đánh giá đạt 4,83/5 trên Naver Shopping. Đây là số liệu bán lẻ nội địa Hàn Quốc, dùng để tham khảo mức độ chấp nhận của người tiêu dùng.","ko":"한국 시장 실적(제조사 자료 기준): 11번가 풋크림 판매 BEST 1위(2020.07.12), 네이버 BEST 100 풋크림 부문 1위(2020.10.22). 2025년 5월 발췌 기준 쿠팡 상품평 31,454건, 네이버쇼핑 리뷰 9,630건 평점 4.83/5. 한국 내수 리테일 지표이며 소비자 수용도 참고용입니다.","en":"Korean market track record per the manufacturer's materials: #1 foot-cream seller on 11st (12 Jul 2020) and #1 in the foot-cream category of Naver BEST 100 (22 Oct 2020). As captured in May 2025: 31,454 reviews on Coupang and 9,630 reviews averaging 4.83/5 on Naver Shopping. These are Korean domestic retail figures, offered as a proxy for consumer acceptance."}},{"type":"p","text":{"vi":"Cách dùng: da sừng ít — dùng 2–3 lần/tuần, rửa chân, lau khô rồi massage cho kem thấm. Da sừng nhiều — dùng từ 5 lần/tuần trở lên, ngâm chân nước ấm, lau khô rồi massage. Bôi trước khi ngủ và mang tất sẽ cho hiệu quả tốt hơn.","ko":"사용법: 각질이 적은 경우 주 2~3회 — 발을 씻고 물기를 없앤 뒤 마사지하듯 발라 흡수시킵니다. 각질이 많은 경우 주 5회 이상 — 따뜻한 물에 발을 불린 뒤 물기를 제거하고 마사지하듯 흡수시킵니다. 자기 전에 바르고 수면양말을 신으면 효과가 더 좋습니다.","en":"How to use: for light calluses, apply 2–3 times a week — wash feet, pat dry, then massage in until absorbed. For heavy calluses, apply 5 or more times a week — soak feet in warm water, dry, then massage in. Applying before bed and wearing socks improves results."}},{"type":"p","text":{"vi":"Thông tin sản phẩm: dung tích 110g · sản xuất tại Hàn Quốc · nhà sản xuất và chịu trách nhiệm phân phối: WELLBEING HEALTHFARM Co., Ltd. · dùng được cho mọi loại da · hạn dùng sau khi mở nắp 12 tháng · số bằng sáng chế 10-1777280. Dòng sản phẩm gồm 3 phiên bản: Goeunbal Premium 110g (sữa ong chúa + keo ong), WHB Goeunbal 100g (dưỡng ẩm) và Cheongchun Goeunbal 100g.","ko":"제품 정보: 용량 110g · 제조국 대한민국 · 제조업자 및 책임판매업자 (주)웰빙헬스팜 · 모든 피부에 사용 · 개봉 후 사용기간 12개월 · 특허 제10-1777280호. 라인업은 명품 고운발 110g(로얄젤리·프로폴리스), WHB 고운발 100g(보습), 청춘 고운발 100g 3종입니다.","en":"Product information: 110g · made in Korea · manufacturer and responsible distributor WELLBEING HEALTHFARM Co., Ltd. · suitable for all skin types · 12 months after opening · patent no. 10-1777280. The line comprises Goeunbal Premium 110g (royal jelly + propolis), WHB Goeunbal 100g (moisturizing) and Cheongchun Goeunbal 100g."}},{"type":"p","text":{"vi":"Khí hậu nóng ẩm và thói quen đi dép hở của người Việt khiến nhu cầu chăm sóc gót chân tăng cao — dòng foot cream Hàn Quốc có dư địa tốt tại kênh nhà thuốc, cửa hàng mỹ phẩm và bán lẻ trực tuyến.","ko":"덥고 습한 기후와 샌들 착용 문화로 베트남의 발 관리 수요가 높아, 한국산 풋크림은 약국·화장품 매장·온라인 리테일 채널에서 성장 여지가 큽니다.","en":"Vietnam's hot, humid climate and open-sandal culture drive strong foot-care demand — Korean foot creams have room to grow across pharmacies, cosmetics stores and online retail."}},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/01.jpg","w":861,"h":3002},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/03.jpg","w":861,"h":2006},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/04.jpg","w":861,"h":3561},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/05.jpg","w":861,"h":3201},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/06.jpg","w":861,"h":2921},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/02.jpg","w":861,"h":2010},{"type":"img","seq":true,"src":"assets/img/products/goeunbal/07.jpg","w":861,"h":2986}]$json$::jsonb
where id = 'p9';

